// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

contract ExzoBlockBase {
    function _msgSender() internal view virtual returns (address) {
        return msg.sender;
    }
}

abstract contract Ownable is ExzoBlockBase {
    address private _owner;
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);

    constructor(address initialOwner) {
        require(initialOwner != address(0), "Initial owner cannot be zero address");
        _transferOwnership(initialOwner);
    }

    modifier onlyOwner() {
        require(owner() == _msgSender(), "OC");
        _;
    }

    function owner() public view virtual returns (address) {
        return _owner;
    }

    function transferOwnership(address newOwner) public virtual onlyOwner {
        require(newOwner != address(0), "NZ");
        _transferOwnership(newOwner);
    }

    function _transferOwnership(address newOwner) internal virtual {
        address oldOwner = _owner;
        _owner = newOwner;
        emit OwnershipTransferred(oldOwner, newOwner);
    }
}

abstract contract ReentrancyGuard {
    uint256 private constant _NOT_ENTERED = 1;
    uint256 private constant _ENTERED = 2;
    uint256 private _status;

    constructor() {
        _status = _NOT_ENTERED;
    }

    modifier nonReentrant() {
        require(_status != _ENTERED, "RG");
        _status = _ENTERED;
        _;
        _status = _NOT_ENTERED;
    }
}

contract ExzoBlock is Ownable, ReentrancyGuard {
    event BlockProcessed(uint256 blockNumber, bytes32 blockHash);
    event WithdrawalExecuted(uint256 amount, address recipient);
    
    uint256 public constant MAX_COOLDOWN = 604800; // One week in seconds
    uint256 public constant BLOCK_LOOKBACK = 128;
    uint256 public cooldown = 3600;
    uint256 public threshold = 0.1 ether;
    uint256 public lastWithdrawal;

    constructor(address initialOwner) Ownable(initialOwner) {}

    receive() external payable {
        // Explicit empty block
    }

    function processBlock(uint256 blockNumber) external onlyOwner {
        require(blockNumber < block.number, "BR");
        require(blockNumber >= block.number - BLOCK_LOOKBACK, "BO");
        emit BlockProcessed(blockNumber, blockhash(blockNumber));
    }

    function withdrawToMaster() external onlyOwner nonReentrant {
        require(block.timestamp > lastWithdrawal + cooldown, "CA");
        require(address(this).balance >= threshold, "TM");
        
        uint256 balance = address(this).balance;
        lastWithdrawal = block.timestamp;
        
        (bool success,) = owner().call{value: balance}("");
        require(success, "WF");
        
        emit WithdrawalExecuted(balance, owner());
    }

    function getContractBalance() public view returns (uint256) {
        return address(this).balance;
    }

    function updateConfig(uint256 newThreshold, uint256 newCooldown) external onlyOwner {
        require(newCooldown <= MAX_COOLDOWN, "CL");
        threshold = newThreshold;
        cooldown = newCooldown;
    }
}
